1085: // Test whether a given character code starts an identifier.
1086: bool isIdentifierStart(uint32_t code) {
1087:   if (code < 65) return code == 36;
1088:   if (code < 91) return true;
1089:   if (code < 97) return code == 95;
1090:   if (code < 123) return true;
1091:   if (code <= 0xffff) return code >= 0xaa && isNonASCIIidentifierStartChar(code);
