1100:   if (code < 65) return false;
1101:   if (code < 91) return true;
1102:   if (code < 97) return code == 95;
1103:   if (code < 123) return true;
1104:   if (code <= 0xffff) return code >= 0xaa && isNonASCIIidentifierChar(code);
