              if (ch != '.') break;
              pos++;
              ch = commentWhitespace();
              if (ch != 'h' || !str_eq13(pos + 1, 'a', 's', 'O', 'w', 'n', 'P', 'r', 'o', 'p', 'e', 'r', 't', 'y')) break;
              pos += 14;
              ch = commentWhitespace();
              if (ch != '(') break;
              pos += 1;
              ch = commentWhitespace();
              if (memcmp(pos, it_id_start, it_id_len * sizeof(uint16_t)) != 0) break;
              pos += it_id_len;
              ch = commentWhitespace();
              if (ch != ')') break;
              pos += 1;
            }
            ch = commentWhitespace();
          }
          if (ch != ')') break;
          pos += 1;
          ch = commentWhitespace();
        }
        else break;

        // EXPORTS_IDENTIFIER `[` IDENTIFIER$2 `] =` IDENTIFIER$1 `[` IDENTIFIER$2 `]`
        if (readExportsOrModuleDotExports(ch)) {
          ch = commentWhitespace();
          if (ch != '[') break;
          pos++;
          ch = commentWhitespace();
          if (memcmp(pos, it_id_start, it_id_len * sizeof(uint16_t)) != 0) break;
          pos += it_id_len;
          ch = commentWhitespace();
          if (ch != ']') break;
          pos++;
          ch = commentWhitespace();
          if (ch != '=') break;
          pos++;
          ch = commentWhitespace();
          if (memcmp(pos, id_start, id_len * sizeof(uint16_t)) != 0) break;
          pos += id_len;
          ch = commentWhitespace();
          if (ch != '[') break;
          pos++;
          ch = commentWhitespace();
          if (memcmp(pos, it_id_start, it_id_len * sizeof(uint16_t)) != 0) break;
          pos += it_id_len;
          ch = commentWhitespace();
          if (ch != ']') break;
          pos++;
          ch = commentWhitespace();
          if (ch == ';') {
            pos++;
            ch = commentWhitespace();
          }
        }
